 const label=value=>typeof value==='object'&&value?value[state.lang]||value.en||value.zh||'':String(value??'');
 const locale=()=>state.lang==='zh'?'zh-CN':'en-GB';
 const reviewKey='gyutron.analytics.product-review.v1.'+String(state.principal?.id||'owner');
 let reviewStorageAvailable=true;const reviews=new Map();if(!state.testMode){try{const stored=JSON.parse(localStorage.getItem(reviewKey)||'{}');for(const [key,value] of Object.entries(stored))if(['reviewed','hidden'].includes(value)&&key.length<=300)reviews.set(key,value);}catch{reviewStorageAvailable=false;}}
 const safeKeys=['view','from','to','source_id','currency','country','product','keyword','channel','device','industry','compare','metrics','mode','period','locale','event_type','exclude_tests','group_by','owner_id','chart','profile_email'];
 const drillKeys=['view','metric','from','to','source_id','currency','country','product','keyword','channel','device','industry','compare','bucket_from','bucket_to','series','entity','status','fulfillment_status','q','page','limit','locale','event_type','exclude_tests','group_by','owner_id','profile_email'];
 let chartFocusIntent=null,chartFocusRestoration=null;
 let generation=0,recordRequest=0,controller=null,externalSignal=null,externalAbort=null,params=new URLSearchParams(),packet=null,catalog=[],sources=[],busy=false,dirty=false,destroyed=false,importDraft={csv:'',source_id:'',preview:null},recordRows=[];
 const charts=createAnalyticsCharts({loadRuntime:deps.loadChartsRuntime,lang:()=>state.lang,money,date,onDrill:drill,onRange:applyChartRange,onError:error=>{if(!controller?.signal.aborted&&state.tab==='analytics')toast(text('The chart could not be displayed. Exact values remain available in the data table.','图表暂时无法显示，可在数据表中查看精确值。'));}});
 const current=seq=>!destroyed&&seq===generation&&state.tab==='analytics'&&!controller?.signal.aborted;
 const valueAttr=value=>esc(String(value??''));
 const view=()=>analyticsView(params.get('view')||'overview');
 const action=(title,name,extra='',primary=false,disabled=false,glyph='')=>'<button type="button" class="button'+(primary?' button-primary':'')+'" data-analytics-action="'+name+'" '+extra+(disabled?' disabled':'')+'>'+(glyph?icon(glyph):'')+'<span>'+esc(title)+'</span></button>';
 const href=(next,overrides={})=>{const target=new URLSearchParams(next);for(const [key,value] of Object.entries(overrides)){if(value===null||value==='')target.delete(key);else target.set(key,String(value));}return '#analytics'+(target.size?'?'+target:'');};
 const canImport=()=>['owner','manager'].includes(state.principal?.role);
 const canExport=()=>typeof deps.can==='function'?deps.can('export'):canImport();
 const request=(path,options={})=>api('operations/'+path,{...options,signal:options.signal||controller?.signal});
 function businessToday(){try{return new Intl.DateTimeFormat('en-CA',{timeZone:state.timezone||'Asia/Singapore',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());}catch{return new Date().toISOString().slice(0,10);}}
 function shiftDay(day,count){const instant=Date.parse(day+'T12:00:00Z');return Number.isFinite(instant)?new Date(instant+count*86400000).toISOString().slice(0,10):day;}
 function scopedParams(input=params){const out=new URLSearchParams();for(const key of safeKeys)if(input.get(key))out.set(key,input.get(key));if(!out.has('view'))out.set('view','overview');return out;}
 function viewParams(key){const next=scopedParams();next.set('view',key);for(const field of ['metrics','mode','chart','page','limit','drill','metric','import','entity','record','bucket_from','bucket_to','status','fulfillment_status'])next.delete(field);const allowed={shop:['device'],trade:['country'],delivery:['country'],team:[],visitors:['device','country'],market:['country','industry'],products:['product'],keywords:['keyword'],traffic:['channel','device'],profiles:['country','industry','device'],ai:['channel'],advertising:['channel','keyword'],map:['country','product','keyword','channel','device','industry']}[key]||[];for(const field of ['country','product','keyword','channel','device','industry'])if(!allowed.includes(field))next.delete(field);if(key!=='team')next.delete('owner_id');if(key!=='profiles')next.delete('profile_email');if(key==='team'){next.delete('source_id');next.delete('currency');}return next;}
 function query(input=params){const out=scopedParams(input);out.delete('mode');out.delete('period');out.delete('chart');for(const key of ['page','limit'])if(input.get(key))out.set(key,input.get(key));return out;}
 function drillParams(input={}){const next=scopedParams();for(const key of drillKeys)if(input[key]!==undefined&&input[key]!==null&&input[key]!=='')next.set(key,String(input[key]));next.set('drill','1');next.delete('page');return next;}
 function number(value){try{return new Intl.NumberFormat(locale()).format(BigInt(String(value)));}catch{return String(value??'—');}}
 function decimal(value,max=2,multiplier=1n){
  const match=String(value??'').match(/^(-?)(\d+)(?:\.(\d+))?$/);if(!match)return '—';
  const fraction=match[3]||'',scale=10n**BigInt(fraction.length),precision=10n**BigInt(max);let raw=(BigInt(match[2])*scale+BigInt(fraction||'0'))*multiplier;
  raw=(raw*precision+scale/2n)/scale;const whole=raw/precision,tail=(raw%precision).toString().padStart(max,'0').replace(/0+$/,'');
  const separator=new Intl.NumberFormat(locale()).formatToParts(1.1).find(part=>part.type==='decimal')?.value||'.';return (match[1]&&raw?'-':'')+number(whole)+(tail?separator+tail:'');
 }
 function format(value,unit='count',currency){if(value===null||value===undefined||value==='')return '—';if(unit==='minor'||unit==='money')return currency?money(value,currency):text('Currency required','需指定币种');if(unit==='ratio')return decimal(value,2,100n)+'%';if(unit==='percent')return decimal(value,2)+'%';if(unit==='hours')return decimal(value,2)+text(' h',' 小时');if(unit==='seconds')return decimal(value,2)+text(' s',' 秒');if(/^-?\d+$/.test(String(value)))return number(value);return decimal(value,2);}
 function percentCoordinate(value){const match=String(value??'').match(/^(-?)(\d+)(?:\.(\d+))?$/);if(!match)return value;const fraction=match[3]||'',digits=BigInt(match[2]+fraction)*100n,scale=10n**BigInt(fraction.length);return match[1]+(digits/scale).toString()+(fraction.length?'.'+(digits%scale).toString().padStart(fraction.length,'0'):'');}
 function metricName(metric){return label(metric?.label)||metric?.key||'—';}
 function deviceName(value){const names={desktop:['Desktop','桌面端'],mobile:['Mobile','移动端'],tablet:['Tablet','平板']};return Object.hasOwn(names,value)?text(...names[value]):String(value??'—');}
 function isDeviceChart(chart){return chart?.dimension==='device'||chart?.id==='device-distribution'||/-device(?:-[A-Z]{3})?$/.test(chart?.id||'');}
 function pointLabel(point,chart){const supplied=label(point.label);if(supplied)return supplied;const raw=String(point.x??point.key??'');if(isDeviceChart(chart))return deviceName(raw);if(chart?.id==='customer-data-completeness'){const names={email_recorded:['Email recorded','已记录邮箱'],email_missing:['Email not recorded','未记录邮箱']};if(Object.hasOwn(names,raw))return text(...names[raw]);}return raw;}
