 function panel(title,body,actions='',description=''){return '<section class="analytics-panel"><div class="analytics-panel-header"><div><h2>'+esc(title)+'</h2>'+(description?'<p>'+esc(description)+'</p>':'')+'</div>'+(actions?'<div class="analytics-panel-actions">'+actions+'</div>':'')+'</div>'+body+'</section>';}
 function empty(title,description='',actions=''){return '<div class="analytics-empty">'+icon('analytics')+'<h3>'+esc(title)+'</h3><p>'+esc(description)+'</p>'+actions+'</div>';}
 function download(path,title,filename=''){if(state.testMode)return '<button class="button" type="button" data-demo-action="export" data-demo-path="'+valueAttr('operations/'+path)+'">'+icon('download')+esc(title)+'</button>';return '<a class="button" href="/admin/api/operations/'+valueAttr(path)+'"'+(filename?' download="'+valueAttr(filename)+'"':'')+'>'+icon('download')+esc(title)+'</a>';}
 function navigation(){const active=view(),groups=ANALYTICS_GROUPS.map(group=>'<section class="analytics-nav-group" data-analytics-group="'+group.id+'"><h3>'+esc(label(group))+'</h3>'+ANALYTICS_VIEWS.filter(item=>item.group===group.id).map(item=>'<a data-analytics-nav-view="'+item.key+'" title="'+valueAttr(label(item))+'" href="'+valueAttr(href(viewParams(item.key)))+'"'+(item.key===active.key?' aria-current="page"':'')+'><span>'+esc(label(item))+'</span></a>').join('')+'</section>').join('');return '<aside class="analytics-navigation"><h2>'+esc(text('Data Adviser','数据参谋'))+'</h2><div class="analytics-mobile-navigation"><label for="analytics-view-select">'+esc(text('Analysis workspace','分析工作区'))+'</label><select id="analytics-view-select" data-analytics-view>'+ANALYTICS_GROUPS.map(group=>'<optgroup data-analytics-option-group="'+group.id+'" label="'+valueAttr(label(group))+'">'+ANALYTICS_VIEWS.filter(item=>item.group===group.id).map(item=>'<option value="'+item.key+'"'+(item.key===active.key?' selected':'')+'>'+esc(label(item))+'</option>').join('')+'</optgroup>').join('')+'</select></div><nav class="analytics-nav-groups" aria-label="'+valueAttr(text('Data Adviser sections','数据参谋栏目'))+'">'+groups+'</nav></aside>';}
 let navigationView=null,navigationObserver=null,observedNavigation=null,navigationHeight=0;
 function watchNavigation(scroll){if(scroll===observedNavigation&&navigationObserver)return;navigationObserver?.disconnect();navigationObserver=null;observedNavigation=scroll;navigationHeight=scroll?.clientHeight||0;if(scroll&&typeof globalThis.ResizeObserver==='function'){navigationObserver=new globalThis.ResizeObserver(()=>{if(scroll!==observedNavigation)return;const height=scroll.clientHeight;if(height>0&&height!==navigationHeight){navigationHeight=height;revealActiveNavigation();}});navigationObserver.observe(scroll);}}
 function revealActiveNavigation(){const scroll=page.querySelector('.analytics-nav-groups'),active=page.querySelector('[data-analytics-nav-view="'+view().key+'"]');if(!scroll||!active||!(scroll.clientHeight>0)||typeof active.getBoundingClientRect!=='function'||typeof scroll.getBoundingClientRect!=='function')return;const bounds=scroll.getBoundingClientRect(),item=active.getBoundingClientRect(),padding=8;let delta=0;if(item.top<bounds.top+padding)delta=item.top-bounds.top-padding;else if(item.bottom>bounds.bottom-padding)delta=item.bottom-bounds.bottom+padding;if(delta)scroll.scrollTop=Math.max(0,Math.min(Math.max(0,scroll.scrollHeight-scroll.clientHeight),scroll.scrollTop+delta));}
 function syncNavigation(){const nav=page.querySelector('.analytics-navigation');if(!nav)return;const active=view(),changed=navigationView!==active.key||nav.dataset.language!==state.lang,setText=(element,value)=>{if(element&&element.textContent!==value)element.textContent=value;};setText(nav.querySelector('h2'),text('Data Adviser','数据参谋'));setText(nav.querySelector('.analytics-mobile-navigation label'),text('Analysis workspace','分析工作区'));nav.querySelector('.analytics-nav-groups')?.setAttribute('aria-label',text('Data Adviser sections','数据参谋栏目'));for(const group of ANALYTICS_GROUPS){setText(nav.querySelector('[data-analytics-group="'+group.id+'"] h3'),label(group));nav.querySelector('[data-analytics-option-group="'+group.id+'"]')?.setAttribute('label',label(group));}for(const item of ANALYTICS_VIEWS){const link=nav.querySelector('[data-analytics-nav-view="'+item.key+'"]');if(link){link.setAttribute('href',href(viewParams(item.key)));link.setAttribute('title',label(item));if(item.key===active.key)link.setAttribute('aria-current','page');else link.removeAttribute('aria-current');setText(link.querySelector('span'),label(item));}setText(nav.querySelector('option[value="'+item.key+'"]'),label(item));}const select=nav.querySelector('[data-analytics-view]');if(select)select.value=active.key;navigationView=active.key;nav.dataset.language=state.lang;watchNavigation(nav.querySelector('.analytics-nav-groups'));if(changed)revealActiveNavigation();}
 function chrome(body,actions=''){const active=view(),content=page.querySelector('.analytics-workspace .analytics-content'),html=heading(label(active),['guide','dictionary'].includes(active.key)?active.description[state.lang==='zh'?1:0]:'',actions)+body;if(content&&page.querySelector('.analytics-navigation'))content.innerHTML=html;else page.innerHTML='<div class="analytics-workspace">'+navigation()+'<div class="analytics-content">'+html+'</div></div>';syncNavigation();}

 function selectedChart(){const items=packet?.charts||[];return items.find(chart=>chart.id===params.get('chart'))||items.find(chart=>chart.kind==='line')||items[0];}
 function exportSelection(){const chart=selectedChart(),point=chart?.series?.flatMap(series=>series.points||[]).find(point=>point.drill?.metric),selected=(packet?.metrics||[]).find(metric=>metric.key===point?.drill?.metric&&(!chart.currency||metric.currency===chart.currency)&&metric.value_exact!==null)||(packet?.metrics||[]).find(metric=>metric.value_exact!==null&&metric.status==='available');if(!selected)return null;const scope=drillParams({...selected.drill,metric:selected.key,...(selected.currency?{currency:selected.currency}:{})});scope.delete('drill');scope.delete('chart');scope.delete('period');scope.delete('mode');scope.delete('bucket_from');scope.delete('bucket_to');return {metric:selected,scope};}
 function primaryChartPicker(){if(['map','ai','guide','dictionary'].includes(view().key))return '';const primary=selectedChart();return primary?'<label class="analytics-chart-picker analytics-heading-chart-picker"><span>'+esc(text('Chart indicator','图表指标'))+'</span><select data-analytics-chart aria-label="'+valueAttr(text('Chart indicator','图表指标'))+'">'+(packet.charts||[]).map(chart=>option(chart.id,chartTitle(chart),primary.id)).join('')+'</select></label>':'';}
 function pageActions(){if(['guide','dictionary'].includes(view().key))return '';const selected=exportSelection();return primaryChartPicker()+(canExport()&&selected?download('adviser/export.csv?'+selected.scope,text('Export ','导出')+metricName(selected.metric)):'')+(canImport()?action(text('Import metrics','导入指标'),'import','',false,false,'upload'):'');}
 function option(value,title,selected){return '<option value="'+valueAttr(value)+'"'+(String(value)===String(selected)?' selected':'')+'>'+esc(title)+'</option>';}
