 function dimensionFields(){const perView={shop:['device'],trade:['country'],delivery:['country'],team:['industry'],visitors:['device','country'],market:['country','industry'],products:['product'],keywords:['keyword'],traffic:['channel','device'],profiles:['country','industry','device'],ai:['channel'],advertising:['channel','keyword'],map:[]},names={country:['Country / market','国家 / 市场'],product:['Product / SKU','产品 / SKU'],keyword:['Keyword','关键词'],channel:['Channel','渠道'],device:['Device','设备'],industry:['Industry','行业']};return (perView[view().key]||[]).map(key=>field(text(...names[key]),key,appliedValue(key),key==='device'?{select:[['',text('All devices','全部设备')],['desktop',text('Desktop','桌面端')],['mobile',text('Mobile','移动端')],['tablet',text('Tablet','平板')]]}:{maxLength:catalog.limits?.dimension_length||120})).join('');}
 function partialCoverage(value){if(!value)return false;if(value.complete===false)return true;if(!Array.isArray(value.periods))return false;const dates=appliedDates(),from=value.requested_from||dates.from,to=value.requested_to||dates.to;const intervals=value.periods.map(item=>Array.isArray(item)?item:item&&typeof item==='object'?[item.from||item.date,item.to||item.date_to||item.date]:[]).filter(item=>/^\d{4}-\d{2}-\d{2}$/.test(item[0]||'')&&/^\d{4}-\d{2}-\d{2}$/.test(item[1]||'')).sort((a,b)=>a[0].localeCompare(b[0]));let next=from;for(const [start,end] of intervals){if(end<next||start>to)continue;if(start>next)return true;next=shiftDay(end,1);if(next>to)return false;}return next<=to;}
