 async function discardImport(){if(busy)return;if(dirty&&!await confirmAction(text('Discard the CSV and preview? No aggregate records have been imported.','放弃 CSV 与预览？尚未导入汇总记录。'),text('Discard','放弃')))return;dirty=false;importDraft={csv:'',source_id:'',preview:null};navigate('analytics',scopedParams());}
 function handleSubmit(event){const form=event.target.closest('[data-analytics-form]');if(!form||state.tab!=='analytics')return;event.preventDefault();const type=form.dataset.analyticsForm;if(type==='filters')return filterSubmit(form);if(type==='import')return previewImport(form);if(type==='metrics'){const checked=[...form.querySelectorAll('[name=metrics]:checked')].map(input=>input.value);const error=form.querySelector('[data-analytics-config-error]');if(checked.length<1||checked.length>12){error.textContent=text('Choose between 1 and 12 indicators.','请选择 1 至 12 项指标。');return;}dirty=false;const next=scopedParams();next.set('metrics',checked.join(','));navigate('analytics',next);}}
 function handleInput(event){if(state.tab!=='analytics')return;if(event.target.matches('[data-analytics-metric-search]'))return searchMetrics(event.target);const form=event.target.closest('[data-analytics-form]');if(!form)return;if(form.dataset.analyticsForm==='import'){dirty=true;importDraft.csv=form.querySelector('[name=csv]').value;importDraft.source_id=form.querySelector('[name=source_id]').value;importDraft.preview=null;updatePreview();}else if(form.dataset.analyticsForm==='metrics'){dirty=true;if(event.target.name==='metrics'&&event.target.checked&&form.querySelectorAll('[name=metrics]:checked').length>12){event.target.checked=false;form.querySelector('[data-analytics-config-error]').textContent=text('Choose at most 12 indicators.','最多选择 12 项指标。');}else form.querySelector('[data-analytics-config-error]').textContent='';metricSelectionControls();}else if(form.dataset.analyticsForm==='filters'){const panel=event.target.closest('[data-analytics-filter-panel]');if(panel){panel.dataset.draft='true';const marker=panel.querySelector('[data-analytics-panel-draft]');if(marker)marker.hidden=false;}if(['from','to'].includes(event.target.name))form.dataset.period='custom';}}
 async function handleChange(event){if(state.tab!=='analytics')return;if(event.target.matches('[data-analytics-chart]')){const origin=event.target,next=scopedParams();next.set('chart',origin.value);cancelChartFocus();chartFocusIntent=origin.isConnected&&page.contains(origin)&&document.activeElement===origin?{origin,scope:next.toString(),chartId:origin.value,cancelled:false}:null;navigate('analytics',next);return;}if(event.target.matches('[data-analytics-view]')){const next=viewParams(event.target.value);navigate('analytics',next);return;}if(event.target.matches('[data-analytics-record]')){if(event.target.value!=='')try{await legacyRecord(Number(event.target.value));}catch(error){toast(error.message);}return;}if(event.target.matches('[data-analytics-csv-file]')){const file=event.target.files?.[0],seq=generation;if(!file)return;if(file.size>1048576){importError(text('The CSV exceeds 1 MiB.','CSV 超过 1 MiB。'));event.target.value='';return;}try{const content=await file.text();if(!current(seq))return;const input=page.querySelector('[name=csv]');input.value=content;importDraft.csv=content;importDraft.preview=null;dirty=true;updatePreview();}catch(error){if(current(seq))importError(error);}return;}handleInput(event);}
 function prepareCurrencyPopover(panel){if(!page.contains(panel))return false;const width=Number(globalThis.innerWidth)||Number(document.documentElement?.clientWidth),height=Number(globalThis.innerHeight)||Number(document.documentElement?.clientHeight);if(!(width>0&&height>0))return true;if(width<=767){delete panel.dataset.currencyPlacement;panel.style.removeProperty('--analytics-currency-max-height');return true;}const summary=panel.querySelector('summary'),list=panel.querySelector('.analytics-currency-list');if(!summary||!list||typeof summary.getBoundingClientRect!=='function')return false;const rect=summary.getBoundingClientRect();if(!Number.isFinite(rect.top)||!Number.isFinite(rect.bottom))return false;const margin=12,gap=7,below=Math.max(0,height-margin-rect.bottom-gap),above=Math.max(0,rect.top-margin-gap),desired=Math.min(420,Number(list.scrollHeight)>0?Number(list.scrollHeight)+2:420),side=below>=desired?'below':above>=desired?'above':above>below?'above':'below',available=side==='above'?above:below,maxHeight=Math.floor(Math.min(420,available));if(maxHeight<20){panel.open=false;return false;}panel.dataset.currencyPlacement=side;panel.style.setProperty('--analytics-currency-max-height',maxHeight+'px');return true;}
 function handleCurrencyViewportChange(event){if(state.tab!=='analytics'||event?.target?.closest?.('.analytics-currency-list'))return;const width=Number(globalThis.innerWidth)||Number(document.documentElement?.clientWidth);if(event?.type==='scroll'&&width>0&&width<=767)return;const active=document.activeElement,panel=active?.closest?.('.analytics-currency-details');closeCurrencyDetails();if(panel&&page.contains(panel))panel.querySelector('summary')?.focus({preventScroll:true});}
